mapper.select:
select (select count(*) from Pro_Construction_Plan_List where Pcp_Id=mn.Pcp_Id) as cplTotal, (select sum(Cpl_Planned_Investment) from Pro_Construction_Plan_List where Pcp_Id=mn.Pcp_Id) as cplInvSum, mn.* from Pro_Construction_plan mn
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pcp_Create_Time desc
